// ===== Sedes (Ubicación) =====
function sedes(){const S=window.MILFOR_SEDES||[],C=document.getElementById("sedes");if(!C||!S.length)return;const D=L=="en"?EN:ES,en=L=="en";
 C.innerHTML=S.map((v,i)=>{const nom=en&&v.nombre_en||v.nombre,tx=en&&v.texto_en||v.texto,pin=v.lat!=null&&v.lng!=null;const zo=en&&v.zona_en||v.zona;let h=`<div class="sede" id="sede-${v.id}"><h3>${nom}</h3>${zo?`<p class="zona">${zo}</p>`:""}<p class="dir">${tx}</p>${(en&&v.nota_en||v.nota)?`<p class="nota-sede">${en&&v.nota_en||v.nota}</p>`:""}`+(v.pisos?`<ul class="pisos">${v.pisos.map((f,k)=>`<li><span class="piso-badge" aria-hidden="true">${k+1}</span><div><b>${en&&f.piso_en||f.piso} · ${en&&f.nombre_en||f.nombre}</b><span>${en&&f.desc_en||f.desc}</span></div></li>`).join("")}</ul>`:"");
  if(v.video)h+=`<button type="button" class="sede-video" data-sede-video="${i}" aria-label="${D.m_video}: ${nom}"><img src="videos/${v.video}-poster.webp${v.video_v?`?v=${v.video_v}`:""}" alt="" width="720" height="1280" loading="lazy" decoding="async"><span class="play" aria-hidden="true"></span><span class="ver-video"><span aria-hidden="true">▶</span> ${D.m_video}</span></button>`;
  if(v.mapaImg){const n=v.mapaImg;h+=`<figure class="llegar"><button type="button" data-sede-mapa="${i}" aria-label="${D.u_ampliar}: ${nom}"><picture><source type="image/webp" srcset="fotos/${n}-480.webp 480w, fotos/${n}-800.webp 800w, fotos/${n}-1600.webp 1600w" sizes="(max-width:760px) 92vw, 420px"><img src="fotos/${n}-800.jpg" srcset="fotos/${n}-800.jpg 800w, fotos/${n}-1600.jpg 1600w" sizes="(max-width:760px) 92vw, 420px" width="${v.mapaImg_w||800}" height="${v.mapaImg_h||1000}" loading="lazy" decoding="async" alt="${nom}"></picture><span class="lupa" aria-hidden="true">⤢</span></button><figcaption>${D.u_tocar}</figcaption></figure>`}
  if(pin)h+=`<p class="centro botones"><a class="btn" href="https://www.google.com/maps/dir/?api=1&destination=${v.lat},${v.lng}" target="_blank" rel="noopener">${D.u_gmaps}</a><a class="btn waze" href="https://waze.com/ul?ll=${v.lat},${v.lng}&navigate=yes" target="_blank" rel="noopener">${D.u_waze}</a></p>`;
  {const wn=en&&v.wa_en||v.wa||nom;h+=`<p class="wa-ctx"><a href="${waUrl(en?`Hello Milfor, I'd like information about ${wn}`:`Hola Milfor, quiero información sobre ${wn}`)}" target="_blank" rel="noopener">${WA_ICO}${D.wa_sede}</a></p>`}
  return h+`</div>`}).join("")}
// ===== Menús (Cena / Infantil, pestañas por número de opción) =====
let MI=0,MT="cena";
// Categorías de menú, en el orden en que aparecen en el selector
const MCATS=[{k:"entradas",d:()=>window.MILFOR_MENUS_ENTRADAS,t:"m_t_ent",tag:"m_ent_tag"},{k:"cena",d:()=>window.MILFOR_MENUS,t:"m_t_cena",tag:"m_cena_tag"},{k:"infantil",d:()=>window.MILFOR_MENUS_INFANTIL,t:"m_t_inf",tag:"m_inf_tag"}];
function mcat(){return MCATS.find(c=>c.k==MT)||MCATS[1]}
function menuLista(){return (mcat().d()||[]).slice().sort((a,b)=>a.num-b.num)}
// Nombre de cada opción: "Menú N" (cena), "Menú infantil N", "Entrada N" (EN: Menu N, Kids' menu N, Starter N)
const MENU_NOM={cena:{es:"Menú",en:"Menu"},infantil:{es:"Menú infantil",en:"Kids' menu"},entradas:{es:"Entrada",en:"Starter"}};
function menuNom(m,lg,cat){const c=MENU_NOM[cat||MT]||MENU_NOM.cena;return `${c[lg||(L=="en"?"en":"es")]} ${m.num}`}
function menuTit(m){const en=L=="en";return `${menuNom(m)} · ${(en&&m.lema_en)||m.lema}`}
function menus(){const M=menuLista(),T=document.getElementById("menu-tabs"),P=document.getElementById("menu-panel"),G=document.getElementById("menu-tipo");if(!T||!M.length)return;const D=L=="en"?EN:ES;
 if(MI>=M.length)MI=0;
 if(G)G.innerHTML=MCATS.filter(c=>(c.d()||[]).length).map(c=>`<button type="button" data-tipo="${c.k}" aria-pressed="${MT==c.k}">${D[c.t]}</button>`).join("");
 T.setAttribute("aria-label",D.m_aria);
 T.innerHTML=M.map((m,i)=>`<button type="button" role="tab" aria-selected="${i==MI}" data-m="${i}">${menuNom(m)}</button>`).join("");
 const m=M[MI],en=L=="en",n=m.img;
 P.innerHTML=`<article class="opcion"><div class="poster-wrap"><button type="button" class="poster" data-poster="${MI}" aria-label="${D.lb_ampliar}: ${menuTit(m)}"><picture><source type="image/webp" srcset="fotos/${n}-480.webp 480w, fotos/${n}-800.webp 800w" sizes="(max-width:760px) 80vw, 340px"><img src="fotos/${n}-800.jpg" width="${m.w}" height="${m.h}" loading="lazy" decoding="async" alt="${menuTit(m)}"></picture></button><div class="poster-acc"><button type="button" class="lupa-btn" aria-label="${(L=="en"?EN:ES).lb_ampliar}: ${menuTit(m)}"><span aria-hidden="true">⤢</span></button>${m.video?`<button type="button" class="ver-video" data-video="${m.video}"><span aria-hidden="true">▶</span> ${D.m_video}</button>`:""}</div></div>
 <div class="opcion-txt"><p class="tag">${D[mcat().tag]}</p><h3>${menuNom(m)}</h3><p class="lema">${en&&m.lema_en||m.lema}</p><ul class="platos">${m.platos.map(p=>{const n=en?p[2]:p[0],d=en?p[3]:p[1];return n?`<li><b>${n}:</b> ${d}</li>`:`<li class="solo">${d.charAt(0).toUpperCase()+d.slice(1)}</li>`}).join("")}</ul><p class="wa-ctx izq"><a href="${waUrl(en?`Hello Milfor, I'm interested in ${menuNom(m,"en")}${m.lema_en?` (${m.lema_en})`:""}`:`Hola Milfor, me interesa ${MT=="entradas"?"la":"el"} ${menuNom(m,"es")}${m.lema?` (${m.lema})`:""}`)}" target="_blank" rel="noopener">${WA_ICO}${D.wa_menu}</a></p></div></article>`;
 const act=T.querySelector('[aria-selected="true"]');if(act&&T.scrollWidth>T.clientWidth)T.scrollTo({left:act.offsetLeft-T.clientWidth/2+act.offsetWidth/2,behavior:"smooth"})}
function menuIr(i){const M=menuLista();MI=(i+M.length)%M.length;menus()}
// ===== Cotizar mi evento: arma el mensaje y abre WhatsApp (no se guarda ni se envía nada a un servidor) =====
const COT={es:{hola:"Hola Milfor, quiero cotizar mi evento:",nombre:"Nombre",tipo:"Tipo de evento",fecha:"Fecha aproximada",inv:"Número de invitados",sede:"Sede de interés",com:"Comentario",falta:"Por favor completa: ",oblig:"Falta este dato",campos:{"ct-nombre":"Nombre","ct-tipo":"Tipo de evento","ct-fecha":"Fecha aproximada","ct-inv":"Número de invitados","ct-sede":"Sede de interés","ct-tel":"Teléfono / WhatsApp"},inv_mal:"Escribe un número de invitados entre 1 y 3000.",tel:"Teléfono / WhatsApp",mail:"Correo",tel_mal:"Escribe un número de celular válido, por ejemplo +57 300 000 0000.",mail_mal:"Revisa el correo electrónico; debe tener la forma nombre@correo.com."},
 en:{hola:"Hello Milfor, I'd like a quote for my event:",nombre:"Name",tipo:"Type of event",fecha:"Approximate date",inv:"Number of guests",sede:"Venue of interest",com:"Comment",falta:"Please fill in: ",oblig:"This field is required",campos:{"ct-nombre":"Name","ct-tipo":"Type of event","ct-fecha":"Approximate date","ct-inv":"Number of guests","ct-sede":"Venue of interest","ct-tel":"Phone / WhatsApp"},inv_mal:"Please enter a valid number of guests (1 to 3000).",tel:"Phone / WhatsApp",mail:"Email",tel_mal:"Please enter a valid mobile number, for example +57 300 000 0000.",mail_mal:"Please check your email address; it should look like name@email.com."}};
function cotizar(){const f=document.getElementById("cot-form");if(!f)return;const err=document.getElementById("ct-error"),ok=document.getElementById("ct-ok"),zona=document.getElementById("ct-enviar-zona"),okLink=document.getElementById("ct-ok-link");
 // Mientras el formulario está en pantalla, el aviso de Analytics y el botón flotante se ocultan (antes tapaban "Enviar por WhatsApp" en el celular)
 const sec=document.getElementById("cotizar");if(sec&&"IntersectionObserver" in window){const vis=new Set(),io=new IntersectionObserver(es=>{es.forEach(x=>x.isIntersecting?vis.add(x.target.id):vis.delete(x.target.id));document.body.classList.toggle("en-cotizar",vis.size>0)},{threshold:0});io.observe(sec);const ct=document.getElementById("contacto");if(ct)io.observe(ct)}
 const marca=(x,m)=>{const c=x.closest(".campo");let s=c.querySelector(".campo-err");if(m){x.setAttribute("aria-invalid","true");if(!s){s=document.createElement("span");s.className="campo-err";s.id=x.id+"-err";c.appendChild(s)}s.textContent=m;x.setAttribute("aria-describedby",s.id)}else{x.removeAttribute("aria-invalid");if(s)s.remove();x.removeAttribute("aria-describedby")}};
 f.addEventListener("input",e=>{if(e.target.matches("input,select,textarea"))marca(e.target,"");err.textContent=""});
 document.getElementById("ct-ok-editar").addEventListener("click",()=>{ok.hidden=true;zona.hidden=false;document.getElementById("ct-nombre").focus()});
 f.addEventListener("submit",e=>{e.preventDefault();const T=COT[L=="en"?"en":"es"],lab=id=>document.querySelector(`label[for="${id}"]`).firstChild.textContent.trim();
  const req=["ct-nombre","ct-tel","ct-tipo","ct-fecha","ct-inv","ct-sede"].map(id=>document.getElementById(id));req.forEach(x=>marca(x,""));
  const mal=req.filter(x=>!x.value.trim());const inv=document.getElementById("ct-inv");
  if(mal.length){mal.forEach(x=>marca(x,T.oblig));err.textContent=T.falta+mal.map(x=>T.campos[x.id]||lab(x.id)).join(", ")+".";mal[0].focus({preventScroll:true});mal[0].closest(".campo").scrollIntoView({block:"center",behavior:"smooth"});return}
  const tel=document.getElementById("ct-tel"),mail=document.getElementById("ct-mail");marca(mail,"");
  const fallo=(x,m)=>{marca(x,m);err.textContent=m;x.focus({preventScroll:true});x.closest(".campo").scrollIntoView({block:"center",behavior:"smooth"})};
  // Teléfono: 7 a 15 dígitos (celular colombiano 3xx xxx xxxx, con o sin +57; también números de otros países con +)
  const dig=tel.value.replace(/\D/g,"");if(!/^\+?[\d\s().-]+$/.test(tel.value.trim())||dig.length<7||dig.length>15||(/^3/.test(dig)&&dig.length!=10)||(/^573/.test(dig)&&dig.length!=12)){fallo(tel,T.tel_mal);return}
  const mv=mail.value.trim();if(mv&&!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(mv)){fallo(mail,T.mail_mal);return}
  const n=+inv.value;if(!Number.isInteger(n)||n<1||n>3000){marca(inv,T.inv_mal);err.textContent=T.inv_mal;inv.focus({preventScroll:true});inv.closest(".campo").scrollIntoView({block:"center",behavior:"smooth"});return}
  const txt=id=>{const x=document.getElementById(id);return x.tagName=="SELECT"?x.options[x.selectedIndex].text:x.value.trim()};
  const fv=document.getElementById("ct-fecha").value,[y,m,d]=fv.split("-").map(Number);
  let fecha=fv;try{fecha=new Date(Date.UTC(y,m-1,d)).toLocaleDateString(L=="en"?"en-US":"es-CO",{day:"numeric",month:"long",year:"numeric",timeZone:"UTC"})}catch(_){}
  const com=txt("ct-com");
  const msg=[T.hola,"",`• ${T.nombre}: ${txt("ct-nombre")}`,`• ${T.tel}: ${txt("ct-tel")}`].concat(mv?[`• ${T.mail}: ${mv}`]:[]).concat([`• ${T.tipo}: ${txt("ct-tipo")}`,`• ${T.fecha}: ${fecha}`,`• ${T.inv}: ${n}`,`• ${T.sede}: ${txt("ct-sede")}`]).concat(com?[`• ${T.com}: ${com}`]:[]).join("\n");
  const u="https://wa.me/573212721996?text="+encodeURIComponent(msg);err.textContent="";
  // GA4 por beacon: no frena la navegación (solo tipo, sede e invitados; nada personal)
  ga("cotizacion_enviada",{tipo_evento:document.getElementById("ct-tipo").value,sede:document.getElementById("ct-sede").value,invitados:n,transport_type:"beacon"});
  // Confirmación visible + enlace de respaldo al mismo wa.me
  okLink.href=u;zona.hidden=true;ok.hidden=false;ok.scrollIntoView({block:"center",behavior:"smooth"});try{ok.focus({preventScroll:true})}catch(_){}
  // Celular / navegador de Instagram o Facebook: misma pestaña (window.open suele bloquearse ahí). Computador: pestaña nueva, con respaldo.
  const movil=/Android|iPhone|iPad|iPod|Instagram|FBAN|FBAV|Mobile/i.test(navigator.userAgent)||(window.matchMedia&&matchMedia("(pointer:coarse)").matches);
  if(movil)setTimeout(()=>{location.href=u},450);else{const w=window.open(u,"_blank");if(w){try{w.opener=null}catch(_){}}else location.href=u}});
}
// ===== Google Analytics 4 (eventos personalizados; sin datos personales) =====
function ga(n,p){try{if(typeof gtag=="function")gtag("event",n,p||{})}catch(_){}}
function waOrigen(a){if(a.closest(".hero"))return"hero";if(a.closest(".wa-flot"))return"flotante";if(a.closest("#contacto"))return"contacto";if(a.closest("#cotizar"))return"cotizar-respaldo";if(a.closest(".pie"))return"pie";
 const sd=a.closest(".sede");if(sd)return sd.id;if(a.closest("#menu-panel")){const m=menuLista()[MI];return`menu-${MT}-${m?m.num:MI+1}`}if(a.closest("#menu"))return"menu";return"otro"}
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest("a[href]");if(!a)return;const u=a.getAttribute("href");
 if(/wa\.me\//.test(u))ga("whatsapp_click",{origen:waOrigen(a)});
 else if(a.closest(".sede")&&/google\.com\/maps|waze\.com/.test(u))ga("como_llegar",{destino:/waze/.test(u)?"waze":"maps",sede:a.closest(".sede").id.replace(/^sede-/,"")})},true);
const GA_VIDEOS=new Set();
document.addEventListener("play",e=>{const v=e.target;if(!v||v.tagName!="VIDEO"||v.dataset.noga)return;const m=/videos\/([^/?#]+)\.mp4/.exec(v.currentSrc||v.src||"");if(!m||GA_VIDEOS.has(m[1]))return;GA_VIDEOS.add(m[1]);ga("video_play",{video:m[1],modo:v.closest(".lb")?"toque":"automatico"})},true);
// ===== Enlaces internos (#cotizar, #menu…): el título de la sección queda justo debajo del encabezado fijo =====
function irA(id,suave){const sec=document.getElementById(id);if(!sec)return;const t=sec.querySelector("h2")||sec,hd=document.querySelector(".nav");
 const y=()=>Math.max(0,Math.round(t.getBoundingClientRect().top+scrollY-(hd?hd.getBoundingClientRect().height:0)-14));
 const rm=window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches;const salta=()=>{const r=document.documentElement,b=r.style.scrollBehavior;r.style.scrollBehavior="auto";window.scrollTo(0,y());r.style.scrollBehavior=b};if(suave&&!rm)window.scrollTo({top:y(),behavior:"smooth"});else salta();
 // re-corrige si algo arriba cambió de alto durante el desplazamiento (imágenes que terminan de cargar, etc.)
 let n=0;const fix=()=>{const d=y()-Math.round(scrollY);if(Math.abs(d)>6&&Math.abs(d)<4000)salta();if(++n<4)setTimeout(fix,n==1?500:700)};
 if("onscrollend" in window){let done=false;const on=()=>{if(done)return;done=true;removeEventListener("scrollend",on);fix()};addEventListener("scrollend",on);setTimeout(on,1600)}else setTimeout(fix,900)}
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest('a[href^="#"]');if(!a||e.defaultPrevented||e.button>0||e.metaKey||e.ctrlKey)return;const id=a.getAttribute("href").slice(1);
 if(!id||id=="top"||!document.getElementById(id))return;e.preventDefault();if(location.hash!="#"+id)history.pushState(null,"","#"+id);irA(id,true)});
addEventListener("load",()=>{const id=location.hash.slice(1);if(id&&document.getElementById(id))irA(id,false)});
// Aviso de Google Analytics: discreto, no bloquea, se recuerda en localStorage
function avisoGA(){const A=document.getElementById("aviso-ga");if(!A)return;{const H=document.querySelector(".nav");if(H)H.after(A)}let visto=false;try{visto=localStorage.getItem("milfor-aviso-ga")=="1"}catch(_){}if(visto)return;A.hidden=false;document.body.classList.add("con-aviso");
 const cerrar=()=>{A.hidden=true;document.body.classList.remove("con-aviso");try{localStorage.setItem("milfor-aviso-ga","1")}catch(_){}};document.getElementById("aviso-ok").addEventListener("click",cerrar);A.querySelector('a[href="#privacidad"]').addEventListener("click",cerrar)}
